REPLACE INTO `albums` (`id`,`artist`,`title`,`year`,`country`,`format`,`genre`,`price`,`rent_price`,`popularity`,`stock`,`about`,`cover`,`audio`,`created_at`) VALUES ('1','Radiohead','In Rainbows','2007','UK','vinil','rock','3600.00','199.00','95','4','Седьмой студийный альбом британской рок-группы Radiohead. В 2007 году был выпущен в формате «pay what you want» и стал одним из самых обсуждаемых релизов десятилетия. Grammy за лучший альтернативный альбом.','images/covers/album_1792560391_566.jpg','audio/track_1795095955_343.mp3','2026-10-21 11:59:58');
REPLACE INTO `albums` (`id`,`artist`,`title`,`year`,`country`,`format`,`genre`,`price`,`rent_price`,`popularity`,`stock`,`about`,`cover`,`audio`,`created_at`) VALUES ('2','Pink Floyd','The Dark Side of the Moon','1973','UK','vinil','rock','4200.00','249.00','98','0','Легендарный концептуальный альбом. Один из самых продаваемых альбомов всех времён — более 45 миллионов копий. Тема — давление современной жизни: время, деньги, безумие, смерть.','images/covers/album_1794463979_275.png','audio/track_1795097118_780.mp3','2026-10-21 11:59:58');
REPLACE INTO `albums` (`id`,`artist`,`title`,`year`,`country`,`format`,`genre`,`price`,`rent_price`,`popularity`,`stock`,`about`,`cover`,`audio`,`created_at`) VALUES ('3','Fleetwood Mac','Rumours','1977','USA','vinil','rock','3600.00','199.00','92','1','Одиннадцатый студийный альбом. Записан в период распада отношений внутри группы, что придало песням особую эмоциональную глубину. Grammy за альбом года.','images/covers/album_1794464010_759.jpg','audio/track_1795096597_826.mp3','2026-10-21 11:59:58');
REPLACE INTO `albums` (`id`,`artist`,`title`,`year`,`country`,`format`,`genre`,`price`,`rent_price`,`popularity`,`stock`,`about`,`cover`,`audio`,`created_at`) VALUES ('4','Type O Negative','Life Is Killing Me','2003','USA','cd','metal','1990.00','149.00','78','7','Шестой студийный альбом готик-метал группы из Бруклина. Мрачный юмор, тяжёлые риффы и характерный бас Питера Стилла.','images/covers/album_1794464050_206.png','audio/track_1795096702_462.mp3','2026-10-21 11:59:58');
REPLACE INTO `albums` (`id`,`artist`,`title`,`year`,`country`,`format`,`genre`,`price`,`rent_price`,`popularity`,`stock`,`about`,`cover`,`audio`,`created_at`) VALUES ('5','The Beatles','Love','2006','UK','cd','rock','2400.00','179.00','88','6','Альбом-коллаж, созданный Джорджем и Джайлзом Мартином для шоу Cirque du Soleil. Мэшапы и ремиксы классических треков Beatles.','images/covers/album_1794464094_399.jpg','audio/track_1795097304_500.mp3','2026-10-21 11:59:58');
REPLACE INTO `albums` (`id`,`artist`,`title`,`year`,`country`,`format`,`genre`,`price`,`rent_price`,`popularity`,`stock`,`about`,`cover`,`audio`,`created_at`) VALUES ('6','Tame Impala','Borderline','2019','Australia','cd','rock','1590.00','99.00','70','10','Сингл с альбома The Slow Rush. Психоделический поп с фирменным звучанием Кевина Паркера.','images/covers/album_1794464128_352.webp','audio/track_1795096922_668.mp3','2026-10-21 11:59:58');
REPLACE INTO `albums` (`id`,`artist`,`title`,`year`,`country`,`format`,`genre`,`price`,`rent_price`,`popularity`,`stock`,`about`,`cover`,`audio`,`created_at`) VALUES ('7','Hozier','Nina Cried Power','2018','Ireland','vinil','folk','2990.00','189.00','82','3','EP-альбом ирландского музыканта. Заглавная песня записана совместно с Мавис Стэплс и посвящена песням протеста.','images/covers/album_1794464254_434.jpg','audio/track_1795097153_832.mp3','2026-10-21 11:59:58');
REPLACE INTO `albums` (`id`,`artist`,`title`,`year`,`country`,`format`,`genre`,`price`,`rent_price`,`popularity`,`stock`,`about`,`cover`,`audio`,`created_at`) VALUES ('8','Radiohead','The Bends','1995','UK','cd','rock','1990.00','149.00','85','7','Второй студийный альбом. Переход от гитарного рока к более атмосферному звучанию, ставшему визитной карточкой группы.','images/covers/album_1794464293_579.jpg','audio/track_1795097187_406.mp3','2026-10-21 11:59:58');
